from taf.internal.sw.neat.client.workflow_inventory.v1.apis.tags.definitions_api import DefinitionsApi
from taf.internal.sw.neat.client.workflow_inventory.v1.api_client import ApiClient
from taf.internal.sw.neat.client.workflow_inventory.v1.apis.tags.health_api import HealthApi
from taf.internal.sw.neat.client.workflow_inventory.v1.configuration import Configuration
from taf.sw.neat.utils.get_return_data import get_return_data


class WorkflowInventoryV1(object):
    def __init__(self, conn_details, access_token):
        self.conn_details = conn_details
        self.configuration = Configuration()
        self.configuration.verify_ssl = False
        self.configuration.host = conn_details.make_configuration_host(original_endpoint=self.configuration.get_host_from_settings(index=None))
        self.configuration.access_token = access_token
        api_client = ApiClient(configuration=self.configuration)

        self.definitions_api = DefinitionsApi(api_client)
        self.health_api = HealthApi(api_client)

    def get_workflow_definitions(self, timeout=60, raw=True, **kwargs):
        query_params = {}
        for key, val in kwargs.items():
            query_params[key] = val
        res = self.definitions_api.definitions_get(query_params=query_params, skip_deserialization=raw, timeout=timeout)
        return get_return_data(res, raw=raw)

    def get_workflow_inventory_health(self, raw=True, timeout=60, **kwargs):
        query_params = {}
        for key, val in kwargs.items():
            query_params[key] = val
        res = self.health_api.admin_health_get(query_params=query_params, skip_deserialization=raw, timeout=timeout)
        return get_return_data(res, raw=raw)['data']
